package com.chronos.education.grade.model;
import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Getter @Setter @NoArgsConstructor @Table(name="edu_grade_item",uniqueConstraints=@UniqueConstraint(name="uk_edu_grade_item",columnNames={"gradebook_id","component_id","student_id"}))
public class GradeItem extends BaseEntity { @Column(name="gradebook_id",nullable=false,length=64) private String gradebookId; @Column(name="component_id",nullable=false,length=64) private String componentId; @Column(name="student_id",nullable=false,length=64) private String studentId; @Column(name="raw_score",precision=8,scale=2) private BigDecimal rawScore; @Column(name="converted_score",precision=8,scale=2) private BigDecimal convertedScore; @Column(name="special_status",length=24) private String specialStatus; @Column(length=500) private String remark; @Version @Column(name="row_version",nullable=false) private Long rowVersion=0L; }
